findings.snippet:
wmb();
if (all_devices) {
    sbi_list_for_each_entry(entry, &ipi_dev_node_list, head) {
        if (entry->dev->ipi_send)
            entry->dev->ipi_send(hartindex);
    }
} else {
    ipi_dev->ipi_send(hartindex);
}
return 0;

sbi_ipi_raw_clear(false);
ipi_type = atomic_raw_xchg_ulong(&ipi_data->ipi_type, 0);
ipi_event = 0;
while (ipi_type) {
    if (ipi_type & 1UL) {
        ipi_ops = ipi_ops_array[ipi_event];
        if (ipi_ops)
            ipi_ops->process(scratch);
    }
    ipi_type = ipi_type >> 1;
    ipi_event++;
}

pending_reg  = plicsw.addr + PLICSW_PENDING_BASE + word_index * 4;
/* Set target hart's mip.MSIP */
writel_relaxed(BIT(pending_bit), (void *)pending_reg);

if ((hsm_device_has_hart_hotplug() && (entry_count == init_count)) ||
   (hsm_device_has_hart_secondary_boot() && !init_count)) {
    rc = hsm_device_hart_start(hartid, scratch->warmboot_addr);
} else {
    rc = sbi_ipi_raw_send(hartindex, true);
}

/* In system suspend, the IMSIC will be reset in SiFive platform so
 * we use the CLINT IPI as the wake event.
 */
sbi_ipi_raw_send(sbi_hartid_to_hartindex(hartid), true);
return SBI_OK;
